CREATE OR REPLACE FUNCTION public.apply_quickbooks_account_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  source_account_id TEXT;
  mapped_category_id INTEGER;
  mapped_sub_category_id INTEGER;
BEGIN
  IF NEW.quickbooks_entity_type IS NULL OR NEW.quickbooks_external_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(
    line #>> '{AccountBasedExpenseLineDetail,AccountRef,value}',
    line #>> '{ItemBasedExpenseLineDetail,ItemAccountRef,value}',
    line #>> '{DepositLineDetail,AccountRef,value}',
    line #>> '{SalesItemLineDetail,ItemAccountRef,value}'
  )
  INTO source_account_id
  FROM public.quickbooks_staged_entities q
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(q.payload->'Line', '[]'::jsonb)) line
  WHERE q.organization_id = NEW.org_id
    AND q.entity_type = NEW.quickbooks_entity_type
    AND q.external_id = NEW.quickbooks_external_id
    AND COALESCE(
      line #>> '{AccountBasedExpenseLineDetail,AccountRef,value}',
      line #>> '{ItemBasedExpenseLineDetail,ItemAccountRef,value}',
      line #>> '{DepositLineDetail,AccountRef,value}',
      line #>> '{SalesItemLineDetail,ItemAccountRef,value}'
    ) IS NOT NULL
  LIMIT 1;

  IF source_account_id IS NULL THEN RETURN NEW; END IF;

  SELECT m.category_id, m.sub_category_id
    INTO mapped_category_id, mapped_sub_category_id
    FROM public.quickbooks_account_mappings m
   WHERE m.organization_id = NEW.org_id
     AND m.quickbooks_account_id = source_account_id
     AND m.mapping_kind = 'category';

  IF mapped_category_id IS NOT NULL THEN
    NEW.category_id := mapped_category_id;
    NEW.sub_category_id := mapped_sub_category_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_token_purchase(p_user_id uuid, p_amount integer, p_stripe_customer_id text, p_stripe_payment_intent_id text, p_stripe_price_id text, p_stripe_product_id text, p_use_case text DEFAULT 'Token purchase'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance integer;
  v_existing public.token_transactions%rowtype;
begin
  if p_user_id is null then
    raise exception 'Missing user id';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Token purchase amount must be positive';
  end if;

  if p_stripe_payment_intent_id is null or length(p_stripe_payment_intent_id) = 0 then
    raise exception 'Missing Stripe payment intent id';
  end if;

  select *
  into v_existing
  from public.token_transactions
  where stripe_payment_intent_id = p_stripe_payment_intent_id
    and type = 'purchase'
    and status = 'posted'
  limit 1;

  if found then
    return jsonb_build_object(
      'applied', false,
      'reason', 'already_applied',
      'balance_after', v_existing.balance_after
    );
  end if;

  update public.users
  set token_balance = coalesce(token_balance, 0) + p_amount
  where auth_id::text = p_user_id::text
  returning token_balance into v_balance;

  if v_balance is null then
    raise exception 'User profile not found for auth user %', p_user_id;
  end if;

  insert into public.token_transactions (
    user_id,
    amount,
    balance_after,
    type,
    status,
    use_case,
    stripe_customer_id,
    stripe_payment_intent_id,
    stripe_price_id,
    stripe_product_id
  )
  values (
    p_user_id,
    p_amount,
    v_balance,
    'purchase',
    'posted',
    p_use_case,
    p_stripe_customer_id,
    p_stripe_payment_intent_id,
    p_stripe_price_id,
    p_stripe_product_id
  );

  return jsonb_build_object(
    'applied', true,
    'balance_after', v_balance
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_transaction_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  row_value public.transactions%ROWTYPE;
  action_label TEXT;
BEGIN
  row_value := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  action_label := CASE TG_OP WHEN 'INSERT' THEN 'added' WHEN 'UPDATE' THEN 'updated' ELSE 'deleted' END;

  INSERT INTO public.account_activity_notifications (
    organization_id, event_type, title, description, amount, route, metadata
  ) VALUES (
    row_value.org_id,
    'transaction_' || lower(TG_OP),
    'Transaction ' || action_label,
    COALESCE(NULLIF(row_value.title, ''), NULLIF(row_value.description, ''), 'Transaction') ||
      CASE WHEN row_value.pending THEN ' is pending.' ELSE ' is reflected in approved activity.' END,
    row_value.amount,
    '/user/money',
    jsonb_build_object('transaction_id', row_value.id, 'source',
      CASE WHEN row_value.plaid_transaction_id IS NOT NULL THEN 'plaid'
           WHEN row_value.quickbooks_external_id IS NOT NULL THEN 'quickbooks'
           ELSE 'booksmart' END)
  );
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_token_purchase(p_user_id uuid, p_amount integer, p_stripe_customer_id text, p_stripe_payment_intent_id text, p_stripe_price_id text, p_stripe_product_id text, p_use_case text DEFAULT 'Token purchase refund'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance_before integer;
  v_balance_after integer;
  v_already_refunded integer;
  v_refund_amount integer;
begin
  if p_user_id is null then
    raise exception 'Missing user id';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Token refund amount must be positive';
  end if;

  if p_stripe_payment_intent_id is null or length(p_stripe_payment_intent_id) = 0 then
    raise exception 'Missing Stripe payment intent id';
  end if;

  select coalesce(sum(abs(amount)), 0)
  into v_already_refunded
  from public.token_transactions
  where stripe_payment_intent_id = p_stripe_payment_intent_id
    and type = 'refund'
    and status = 'refunded';

  v_refund_amount := p_amount - v_already_refunded;

  if v_refund_amount <= 0 then
    return jsonb_build_object(
      'applied', false,
      'reason', 'already_refunded',
      'already_refunded_amount', v_already_refunded
    );
  end if;

  select coalesce(token_balance, 0)
  into v_balance_before
  from public.users
  where auth_id::text = p_user_id::text
  for update;

  if v_balance_before is null then
    raise exception 'User profile not found for auth user %', p_user_id;
  end if;

  v_refund_amount := least(v_balance_before, v_refund_amount);
  v_balance_after := v_balance_before - v_refund_amount;

  update public.users
  set token_balance = v_balance_after
  where auth_id::text = p_user_id::text;

  insert into public.token_transactions (
    user_id,
    amount,
    balance_after,
    type,
    status,
    use_case,
    stripe_customer_id,
    stripe_payment_intent_id,
    stripe_price_id,
    stripe_product_id
  )
  values (
    p_user_id,
    -v_refund_amount,
    v_balance_after,
    'refund',
    'refunded',
    p_use_case,
    p_stripe_customer_id,
    p_stripe_payment_intent_id,
    p_stripe_price_id,
    p_stripe_product_id
  );

  return jsonb_build_object(
    'applied', true,
    'deducted_amount', v_refund_amount,
    'balance_after', v_balance_after
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
